import json,hashlib
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).parent;root=out.parent;checks=[]
def note(name,d):checks.append({'check':name,'observed':d});(out/'hf-calibration-review.json').write_text(json.dumps(checks,indent=2,ensure_ascii=False),encoding='utf-8');print(name,str(d)[:400],flush=True)
def styles(page,sel):return page.locator(sel).evaluate('(e)=>{let c=getComputedStyle(e);return {radius:c.borderRadius,height:e.getBoundingClientRect().height,font:c.fontFamily,weight:c.fontWeight,size:c.fontSize,line:c.lineHeight,color:c.color,background:c.backgroundColor,shadow:c.boxShadow,outline:c.outline,offset:c.outlineOffset,transform:c.transform,transition:c.transition,opacity:c.opacity}}')
def fonts(page,sel):
 cdp=page.context.new_cdp_session(page);cdp.send('DOM.enable');cdp.send('CSS.enable');doc=cdp.send('DOM.getDocument');node=cdp.send('DOM.querySelector',{'nodeId':doc['root']['nodeId'],'selector':sel});return cdp.send('CSS.getPlatformFontsForNode',{'nodeId':node['nodeId']})
refs=json.loads((root/'evidence/calibration-reference-check.json').read_text())['selectedManifestHashes'];refroot=root.parent.parent/'_docs/evidence/affect-ui-clean-light';note('Independent selected reference hashes',{f:hashlib.sha256((refroot/f).read_bytes()).hexdigest()==h for f,h in refs.items()});assert all(hashlib.sha256((refroot/f).read_bytes()).hexdigest()==h for f,h in refs.items())
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':1400,'height':1100},device_scale_factor=1);page.goto('http://127.0.0.1:5178/calibration.html');page.evaluate('document.fonts.ready');normal=styles(page,'#normal-sample');secondary=styles(page,'#hover-sample');danger=styles(page,'#danger-sample');note('Rendered default recipe',{'primary':normal,'secondary':secondary,'record':danger,'disabled':styles(page,'button:disabled'),'invalid':styles(page,'#invalid-sample')});assert normal['height']==40 and normal['radius']=='6px' and normal['weight']=='500';assert secondary['background']=='rgb(255, 255, 255)';assert danger['color']=='rgb(193, 38, 44)'
 note('Actual Mabry fonts',{'medium':fonts(page,'#normal-sample'),'regular':fonts(page,'body > p')});page.locator('#hover-sample').hover();page.wait_for_timeout(180);hover=styles(page,'#hover-sample');note('Actual hover',hover);assert hover['shadow']!=secondary['shadow'];page.locator('#hover-sample').click();page.keyboard.press('Tab');assert page.locator('#focus-sample').evaluate('(e)=>e===document.activeElement && e.matches(":focus-visible")');note('Keyboard focus',styles(page,'#focus-sample'));page.screenshot(path=str(out/'hf-review-calibration-focus.png'),full_page=True)
 box=page.locator('#normal-sample').bounding_box();page.mouse.move(box['x']+box['width']/2,box['y']+box['height']/2);page.mouse.down();page.wait_for_timeout(180);pressed=styles(page,'#normal-sample');assert '0.97' in pressed['transform'];page.mouse.up();page.mouse.move(1300,1000);page.wait_for_timeout(200);reverse=styles(page,'#normal-sample');assert reverse['transform'] in ['none','matrix(1, 0, 0, 1, 0, 0)'];note('Held press and reverse',{'pressed':pressed['transform'],'released':reverse['transform']})
 spin=page.locator('#loading-sample svg').evaluate('(e)=>({name:getComputedStyle(e).animationName,duration:getComputedStyle(e).animationDuration})');page.emulate_media(reduced_motion='reduce');reduced=page.locator('#loading-sample svg').evaluate('(e)=>({name:getComputedStyle(e).animationName,duration:getComputedStyle(e).animationDuration})');note('Busy pending reduced motion',{'normal':spin,'reduced':reduced});assert reduced['name']=='none'
 page.set_viewport_size({'width':390,'height':844});page.screenshot(path=str(out/'hf-review-calibration-phone.png'),full_page=True);assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');note('Calibration phone targets',page.locator('#normal-sample,#hover-sample,#danger-sample,#invalid-sample').evaluate_all('(es)=>es.map(e=>({id:e.id,rect:e.getBoundingClientRect().toJSON()}))'));assert all(e['height']>=48 for e in [page.locator(x).bounding_box() for x in ['#normal-sample','#hover-sample','#danger-sample','#invalid-sample']]);b.close()
